stale as (
  delete from public.venue_sports vs using public.venues v
   where v.id = vs.venue_id and v.locally_edited_at is null
     and vs.venue_id in (select distinct s.venue_id from src s)
     and not exists (select 1 from src s where s.venue_id = vs.venue_id and s.sport_id = vs.sport_id))
insert into public.venue_sports (venue_id, sport_id, inferred)
select s.venue_id, s.sport_id, s.inferred from src s join public.venues v on v.id = s.venue_id
 where v.locally_edited_at is null
on conflict (venue_id, sport_id) do update set inferred = excluded.inferred;

-- OSM objects that disappeared since an earlier import: soft-delete (events may reference them).
update public.venues v set status = 'hidden'
 where v.source = 'osm' and v.status = 'active' and v.locally_edited_at is null
   and v.osm_imported_at < '2026-10-15T14:38:57Z'::timestamptz;
